import fs from 'fs';
import path from 'path';
import os from 'os';
import { createLogger } from './logger';
import {
  CLAUDE_SKILL_VERSION,
  CLAUDE_SKILL_CONTENT,
  CLAUDE_SKILL_DIR,
  CLAUDE_SKILL_FILENAME,
} from './skills/claude-skill';
import {
  CURSOR_RULES_VERSION,
  CURSOR_RULES_CONTENT,
  CURSOR_RULES_FILENAME,
} from './skills/cursor-rules';
import {
  RIVET_WORKER_AGENT_DEFINITIONS,
  RIVET_WORKER_AGENT_FILENAME,
  RIVET_WORKER_AGENT_VERSION,
} from '../hosts/workerDefaults';
import { errorMessage } from './errorMessage';
import { writeAgentSkill } from '../install/agentSkill';

type AgentFile = {
  filePath: string;
  directories: string[];
  ownedDirectory?: string;
  versionMarker: RegExp;
};

const CLAUDE_SKILL_VERSION_PATTERN =
  /^\[\/\/\]: # \(rivet-skill-version:\s*(\d+)\)\r?$/m;
const WORKER_AGENT_VERSION_PATTERN =
  /^\[\/\/\]: # \(rivet-worker-agent-version:\s*(\d+)\)\r?$/m;
const CLAUDE_SKILL_MARKER = '[//]: # (rivet-skill-version:';
const WORKER_AGENT_MARKER = '[//]: # (rivet-worker-agent-version:';

const log = createLogger('SkillWriter');

function getInstalledVersion(content: string, pattern: RegExp): number {
  const match = content.match(pattern);
  return match ? parseInt(match[1], 10) : 0;
}

type SkillWriteResult = { success: true } | { success: false; error: string };

const isAgentDirectory = (directoryPath: string, isShared = false): boolean => {
  const readStatus = isShared ? fs.statSync : fs.lstatSync;
  const existing = readStatus(directoryPath, { throwIfNoEntry: false });
  return !existing || existing.isDirectory();
};

const hasAgentFile = ({
  filePath,
  directories,
  ownedDirectory,
  versionMarker,
}: AgentFile): boolean => {
  try {
    return (
      directories.every((directory) => isAgentDirectory(directory, true)) &&
      (!ownedDirectory || isAgentDirectory(ownedDirectory)) &&
      fs.lstatSync(filePath).isFile() &&
      getInstalledVersion(fs.readFileSync(filePath, 'utf8'), versionMarker) > 0
    );
  } catch {
    return false;
  }
};

const agentFileConflict = (file: AgentFile): string | undefined => {
  const directory = file.directories.find(
    (candidate) => !isAgentDirectory(candidate, true),
  );
  const ownedDirectory =
    file.ownedDirectory && !isAgentDirectory(file.ownedDirectory)
      ? file.ownedDirectory
      : undefined;
  const existing = fs.lstatSync(file.filePath, { throwIfNoEntry: false });
  const conflictPath =
    directory ??
    ownedDirectory ??
    (existing && !hasAgentFile(file) ? file.filePath : undefined);
  return conflictPath
    ? `A user-managed file or symlink exists at ${conflictPath}. Move or rename it before installing Rivet.`
    : undefined;
};

export const claudeSkillPath = (): string =>
  path.join(
    os.homedir(),
    '.claude',
    'skills',
    CLAUDE_SKILL_DIR,
    CLAUDE_SKILL_FILENAME,
  );

const claudeSkillFile = (): AgentFile => ({
  filePath: claudeSkillPath(),
  directories: [
    path.join(os.homedir(), '.claude'),
    path.join(os.homedir(), '.claude', 'skills'),
  ],
  ownedDirectory: path.dirname(claudeSkillPath()),
  versionMarker: CLAUDE_SKILL_VERSION_PATTERN,
});

export const hasClaudeSkill = (): boolean => hasAgentFile(claudeSkillFile());

export const writeSkillFileIfNeeded = (): SkillWriteResult => {
  try {
    const skill = claudeSkillFile();
    const conflict = agentFileConflict(skill);
    if (conflict) return { success: false, error: conflict };
    if (
      hasClaudeSkill() &&
      getInstalledVersion(
        fs.readFileSync(skill.filePath, 'utf8'),
        CLAUDE_SKILL_VERSION_PATTERN,
      ) >= CLAUDE_SKILL_VERSION
    )
      return { success: true };

    const result = writeAgentSkill({
      filePath: skill.filePath,
      content: CLAUDE_SKILL_CONTENT,
      marker: CLAUDE_SKILL_MARKER,
    });
    if (!result.ok) return { success: false, error: result.error };
    log.info('Wrote Rivet Claude skill file');
    return { success: true };
  } catch (error) {
    const message = errorMessage(error);
    const code =
      error instanceof Error && 'code' in error
        ? (error as Error & { code?: string }).code
        : '';
    log.debug('Could not write skill file:', error);
    return { success: false, error: code ? `${code}: ${message}` : message };
  }
};

export function claudeWorkerAgentPath(): string {
  return path.join(
    os.homedir(),
    '.claude',
    'agents',
    RIVET_WORKER_AGENT_FILENAME,
  );
}

export const claudeWorkerAgentPaths = (): string[] =>
  Object.values(RIVET_WORKER_AGENT_DEFINITIONS).map((definition) =>
    path.join(os.homedir(), '.claude', 'agents', definition.filename),
  );

const claudeWorkerFile = (filePath: string): AgentFile => ({
  filePath,
  directories: [
    path.join(os.homedir(), '.claude'),
    path.join(os.homedir(), '.claude', 'agents'),
  ],
  versionMarker: WORKER_AGENT_VERSION_PATTERN,
});

export const hasClaudeWorkerAgent = (filePath: string): boolean =>
  hasAgentFile(claudeWorkerFile(filePath));

export const writeWorkerAgentIfNeeded = (): SkillWriteResult => {
  try {
    for (const filePath of claudeWorkerAgentPaths()) {
      const conflict = agentFileConflict(claudeWorkerFile(filePath));
      if (conflict) return { success: false, error: conflict };
    }
    for (const definition of Object.values(RIVET_WORKER_AGENT_DEFINITIONS)) {
      const agentPath = path.join(
        os.homedir(),
        '.claude',
        'agents',
        definition.filename,
      );
      if (
        hasClaudeWorkerAgent(agentPath) &&
        getInstalledVersion(
          fs.readFileSync(agentPath, 'utf8'),
          WORKER_AGENT_VERSION_PATTERN,
        ) >= RIVET_WORKER_AGENT_VERSION
      )
        continue;
      const result = writeAgentSkill({
        filePath: agentPath,
        content: definition.content,
        marker: WORKER_AGENT_MARKER,
      });
      if (!result.ok) return { success: false, error: result.error };
    }
    log.info('Wrote Rivet worker agent definitions for Claude Code');
    return { success: true };
  } catch (error) {
    const message = errorMessage(error);
    const code =
      error instanceof Error && 'code' in error
        ? (error as Error & { code?: string }).code
        : '';
    log.debug('Could not write worker agent definition:', error);
    return { success: false, error: code ? `${code}: ${message}` : message };
  }
};

export function writeCursorRulesIfNeeded(projectPath: string): boolean {
  try {
    const rulesDir = path.join(projectPath, '.cursor', 'rules');
    const rulesPath = path.join(rulesDir, CURSOR_RULES_FILENAME);

    if (fs.existsSync(rulesPath)) {
      const existing = fs.readFileSync(rulesPath, 'utf8');
      const installed = getInstalledVersion(
        existing,
        /rivet-rules-version:\s*(\d+)/,
      );
      if (installed >= CURSOR_RULES_VERSION) return true;
    }

    if (!fs.existsSync(rulesDir)) {
      fs.mkdirSync(rulesDir, { recursive: true });
    }

    fs.writeFileSync(rulesPath, CURSOR_RULES_CONTENT, 'utf8');
    log.info('Wrote Rivet Cursor rules file');
    return true;
  } catch (error) {
    log.debug('Could not write Cursor rules file:', error);
    return false;
  }
}
